<?php
/** Customer-safe quote REST API. @package SmashPro */
if ( ! defined( 'ABSPATH' ) ) { exit; }
function smashpro_quote_api_token( WP_REST_Request $request ) { $token = strtolower( trim( (string) $request['token'] ) ); return preg_match( '/^[a-f0-9]{64}$/', $token ) ? $token : ''; }
function smashpro_quote_api_context( $token ) { global $wpdb; if ( '' === $token ) return new WP_Error( 'invalid_quote', 'This quote link is invalid.', array( 'status'=>404 ) ); $link=$wpdb->get_row($wpdb->prepare("SELECT * FROM sp_quote_links WHERE token=%s AND status='active' AND (expires_at IS NULL OR expires_at > NOW()) LIMIT 1",$token),ARRAY_A); if(!$link)return new WP_Error('quote_unavailable','This quote link is no longer active.',array('status'=>404)); $quote=$wpdb->get_row($wpdb->prepare('SELECT * FROM sp_job_quotes WHERE id=%d LIMIT 1',(int)$link['quote_id']),ARRAY_A); $job=$wpdb->get_row($wpdb->prepare('SELECT * FROM spd_jobs WHERE id=%d LIMIT 1',(int)$link['job_id']),ARRAY_A); $customer=!empty($link['customer_id'])?$wpdb->get_row($wpdb->prepare('SELECT * FROM spd_customers WHERE id=%d LIMIT 1',(int)$link['customer_id']),ARRAY_A):null; if(!$quote||!$job)return new WP_Error('quote_missing','This quote could not be found.',array('status'=>404)); return compact('link','quote','job','customer'); }
function smashpro_quote_api_option($quote,$key){return array('key'=>$key,'label'=>sanitize_text_field((string)($quote[$key.'_label']??'')),'price'=>sanitize_text_field((string)($quote[$key.'_price']??'')),'description'=>sanitize_textarea_field((string)($quote[$key.'_description']??'')));}
function smashpro_quote_api_get(WP_REST_Request $request){global $wpdb;$ctx=smashpro_quote_api_context(smashpro_quote_api_token($request));if(is_wp_error($ctx))return $ctx;$link=$ctx['link'];$quote=$ctx['quote'];$job=$ctx['job'];$customer=$ctx['customer'];$wpdb->update('sp_quote_links',array('last_viewed_at'=>current_time('mysql')),array('id'=>(int)$link['id']));$options=array_values(array_filter(array_map(function($key)use($quote){$option=smashpro_quote_api_option($quote,$key);return(''!==$option['label']||''!==$option['price'])?$option:null;},array('good','better','best'))));$photos=array();if(!empty($job['image_urls'])){$decoded=json_decode((string)$job['image_urls'],true);if(is_array($decoded))foreach($decoded as $url)if(is_string($url)&&0===strpos($url,'/'))$photos[]=esc_url_raw(home_url($url));}$messages=$wpdb->get_results($wpdb->prepare('SELECT sender,message,created_at FROM sp_quote_messages WHERE quote_id=%d ORDER BY created_at ASC LIMIT 50',(int)$quote['id']),ARRAY_A);return rest_ensure_response(array('customerName'=>sanitize_text_field((string)($customer['name']??'')),'serviceName'=>sanitize_text_field((string)($job['service_name']??($quote['quote_title']??'SmashPro quote'))),'summary'=>sanitize_textarea_field((string)($quote['summary']??($quote['quote_description']??''))),'status'=>sanitize_key((string)($quote['status']??'')),'customerResponseStatus'=>sanitize_key((string)($quote['customer_response_status']??'')),'recommendedOption'=>sanitize_key((string)($quote['recommended_option']??'')),'approvedOption'=>sanitize_key((string)($quote['approved_option']??'')),'approvedPrice'=>sanitize_text_field((string)($quote['approved_price']??'')),'options'=>$options,'photos'=>array_values(array_unique($photos)),'messages'=>array_map(function($message){return array('sender'=>sanitize_key((string)$message['sender']),'message'=>sanitize_textarea_field((string)$message['message']),'createdAt'=>(string)$message['created_at']);},$messages?:array()),'deposit'=>array('required'=>1===(int)($quote['deposit_required']??0),'paid'=>1===(int)($quote['deposit_paid']??0)||'paid'===strtolower((string)($quote['deposit_status']??'')),'amountCents'=>(int)($quote['deposit_amount_cents']??0),'paymentUrl'=>esc_url_raw((string)($quote['stripe_payment_link']??'')))));}
function smashpro_quote_api_approve(WP_REST_Request $request){global $wpdb;$ctx=smashpro_quote_api_context(smashpro_quote_api_token($request));if(is_wp_error($ctx))return $ctx;$option=sanitize_key((string)$request->get_param('option'));if(!in_array($option,array('good','better','best'),true))return new WP_Error('invalid_option','Choose a valid quote option.',array('status'=>400));$selected=smashpro_quote_api_option($ctx['quote'],$option);if(''===$selected['price']&&''===$selected['label'])return new WP_Error('unavailable_option','That quote option is unavailable.',array('status'=>400));$wpdb->update('sp_job_quotes',array('status'=>'quote_approved','approved_option'=>$option,'approved_price'=>$selected['price'],'approved_at'=>current_time('mysql'),'approval_source'=>'web_portal','approved_by_customer_id'=>(int)($ctx['link']['customer_id']??0),'customer_response_status'=>'quote_approved','updated_at'=>current_time('mysql')),array('id'=>(int)$ctx['quote']['id']));$wpdb->update('spd_jobs',array('status'=>'quote_approved','updated_at'=>current_time('mysql')),array('id'=>(int)$ctx['job']['id']));return rest_ensure_response(array('ok'=>true,'approvedOption'=>$option,'approvedPrice'=>$selected['price']));}
function smashpro_quote_api_message(WP_REST_Request $request){global $wpdb;$ctx=smashpro_quote_api_context(smashpro_quote_api_token($request));if(is_wp_error($ctx))return $ctx;$message=sanitize_textarea_field((string)$request->get_param('message'));if(''===trim($message))return new WP_Error('empty_message','Add a message before sending.',array('status'=>400));$wpdb->insert('sp_quote_messages',array('job_id'=>(int)$ctx['job']['id'],'quote_id'=>(int)$ctx['quote']['id'],'customer_id'=>(int)($ctx['link']['customer_id']??0),'sender'=>'customer','message'=>$message,'created_at'=>current_time('mysql')));$wpdb->update('sp_job_quotes',array('customer_response_status'=>'waiting_on_customer','updated_at'=>current_time('mysql')),array('id'=>(int)$ctx['quote']['id']));return rest_ensure_response(array('ok'=>true));}
function smashpro_quote_api_register(){register_rest_route('smashpro/v1','/quote/(?P<token>[a-fA-F0-9]{64})',array('methods'=>'GET','callback'=>'smashpro_quote_api_get','permission_callback'=>'__return_true'));register_rest_route('smashpro/v1','/quote/(?P<token>[a-fA-F0-9]{64})/approve',array('methods'=>'POST','callback'=>'smashpro_quote_api_approve','permission_callback'=>'__return_true'));register_rest_route('smashpro/v1','/quote/(?P<token>[a-fA-F0-9]{64})/message',array('methods'=>'POST','callback'=>'smashpro_quote_api_message','permission_callback'=>'__return_true'));}
add_action('rest_api_init','smashpro_quote_api_register');
